#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
import argparse
from pathlib import Path
import subprocess
import tempfile

here = Path(__file__).resolve().parent
parser = argparse.ArgumentParser()
parser.add_argument('--glslc', default='glslc')
parser.add_argument('--spirv-val', default='')
a = parser.parse_args()

shaders = [
    ('nvk_mesh_emu_tclamp_spv', 'mxe_tclamp.comp'),
    ('nvk_mesh_emu_scan_spv', 'mxe_scan.comp'),
    ('nvk_mesh_emu_monly_spv', 'mxe_monly.comp'),
]

lines = [
    '// SPDX-License-Identifier: Apache-2.0',
    '// Generated by mesh_emu_shaders/generate.py (Vulkan 1.1).',
    '#pragma once',
    '#include <stdint.h>',
    '',
]

build_dir = here.parents[3] / 'build'
build_dir.mkdir(parents=True, exist_ok=True)
with tempfile.TemporaryDirectory(dir=build_dir) as tmp:
    for sym, fname in shaders:
        out = Path(tmp) / f'{sym}.spv'
        subprocess.run([a.glslc, '--target-env=vulkan1.1', '-O', str(here / fname), '-o', str(out)], check=True)
        if a.spirv_val:
            subprocess.run([a.spirv_val, '--target-env', 'vulkan1.1', str(out)], check=True)
        b = out.read_bytes()
        if len(b) % 4:
            raise ValueError(f'{fname}: SPIR-V not word aligned')
        words = [int.from_bytes(b[i:i + 4], 'little') for i in range(0, len(b), 4)]
        lines.append(f'static const uint32_t {sym}[] = {{')
        lines += ['    ' + ', '.join('0x%08xu' % w for w in words[i:i + 8]) + ',' for i in range(0, len(words), 8)]
        lines.append('};')
        lines.append('')

(here.parent / 'backend_vulkan_mesh_emu_spv.h').write_text('\n'.join(lines))
